#!/usr/bin/env python3
"""
Motorola 68000 Disassembler
Supports most common 68000 instructions and addressing modes
"""

import sys
import struct

class M68kDisassembler:
    def __init__(self):
        self.pc = 0
        self.data = b''
        self.cycles = 0
        self.has_mem_access = False  # Track if instruction accesses memory

    def read_word(self):
        """Read a 16-bit word from the instruction stream"""
        if self.pc + 2 > len(self.data):
            raise Exception("Unexpected end of data")
        word = struct.unpack('>H', self.data[self.pc:self.pc+2])[0]
        self.pc += 2
        return word

    def read_long(self):
        """Read a 32-bit long from the instruction stream"""
        if self.pc + 4 > len(self.data):
            raise Exception("Unexpected end of data")
        long = struct.unpack('>I', self.data[self.pc:self.pc+4])[0]
        self.pc += 4
        return long

    def get_size_suffix(self, size):
        """Convert size code to assembly suffix"""
        return {0: '.B', 1: '.W', 2: '.L'}[size]

    def get_ea_cycles(self, mode, reg, size):
        """Get effective address access time in clock cycles"""
        # Returns (read_cycles, write_cycles)
        if mode == 0:  # Dn
            return (0, 0)
        elif mode == 1:  # An
            return (0, 0)
        elif mode == 2:  # (An)
            if size == 2:  # long
                return (8, 8)
            else:
                return (4, 4)
        elif mode == 3:  # (An)+
            if size == 2:
                return (8, 8)
            else:
                return (4, 4)
        elif mode == 4:  # -(An)
            if size == 2:
                return (10, 8)
            else:
                return (6, 4)
        elif mode == 5:  # d16(An)
            if size == 2:
                return (12, 12)
            else:
                return (8, 8)
        elif mode == 6:  # d8(An,Xn)
            if size == 2:
                return (14, 14)
            else:
                return (10, 10)
        elif mode == 7:
            if reg == 0:  # xxx.W
                if size == 2:
                    return (12, 12)
                else:
                    return (8, 8)
            elif reg == 1:  # xxx.L
                if size == 2:
                    return (16, 16)
                else:
                    return (12, 12)
            elif reg == 2:  # d16(PC)
                if size == 2:
                    return (12, 0)
                else:
                    return (8, 0)
            elif reg == 3:  # d8(PC,Xn)
                if size == 2:
                    return (14, 0)
                else:
                    return (10, 0)
            elif reg == 4:  # #imm
                if size == 2:
                    return (8, 0)
                elif size == 1:
                    return (4, 0)
                else:  # byte
                    return (4, 0)
        return (0, 0)

    def format_cycles(self, cycles, has_mem_access):
        """Format cycle count with memory access notation"""
        if has_mem_access:
            return f"{cycles}+ cycles"
        else:
            return f"{cycles} cycles"

    def check_mem_access(self, mode, reg=None):
        """Check if addressing mode involves data memory access (not instruction fetch)"""
        if mode <= 1:  # Dn, An - no memory access
            return False
        elif mode >= 2 and mode <= 6:  # (An), (An)+, -(An), d(An), d(An,Xn) - all access memory
            return True
        elif mode == 7:  # Special modes
            if reg is None:
                return True  # Conservative default
            if reg == 4:  # Immediate - no data memory access (instruction stream only)
                return False
            elif reg in [2, 3]:  # PC-relative modes - no data memory access in typical sense
                return False
            else:  # Absolute addressing - accesses memory
                return True
        return False

    def get_condition(self, cc):
        """Get condition code mnemonic"""
        conditions = [
            'T', 'F', 'HI', 'LS', 'CC', 'CS', 'NE', 'EQ',
            'VC', 'VS', 'PL', 'MI', 'GE', 'LT', 'GT', 'LE'
        ]
        return conditions[cc]

    def decode_ea(self, mode, reg, size):
        """Decode effective address"""
        if mode == 0:  # Dn
            return f"D{reg}"
        elif mode == 1:  # An
            return f"A{reg}"
        elif mode == 2:  # (An)
            return f"(A{reg})"
        elif mode == 3:  # (An)+
            return f"(A{reg})+"
        elif mode == 4:  # -(An)
            return f"-(A{reg})"
        elif mode == 5:  # d16(An)
            disp = self.read_word()
            disp_signed = disp if disp < 0x8000 else disp - 0x10000
            return f"${disp_signed:X}(A{reg})"
        elif mode == 6:  # d8(An,Xn)
            ext = self.read_word()
            xreg = (ext >> 12) & 7
            xtype = 'A' if (ext & 0x8000) else 'D'
            xsize = '.l' if (ext & 0x800) else '.w'
            disp = ext & 0xFF
            disp_signed = disp if disp < 0x80 else disp - 0x100
            return f"${disp_signed:X}(A{reg},{xtype}{xreg}{xsize})"
        elif mode == 7:
            if reg == 0:  # xxx.W
                addr = self.read_word()
                return f"${addr:04X}.w"
            elif reg == 1:  # xxx.L
                addr = self.read_long()
                return f"${addr:08X}.l"
            elif reg == 2:  # d16(PC)
                disp = self.read_word()
                disp_signed = disp if disp < 0x8000 else disp - 0x10000
                return f"${disp_signed:X}(PC)"
            elif reg == 3:  # d8(PC,Xn)
                ext = self.read_word()
                xreg = (ext >> 12) & 7
                xtype = 'A' if (ext & 0x8000) else 'D'
                xsize = '.l' if (ext & 0x800) else '.w'
                disp = ext & 0xFF
                disp_signed = disp if disp < 0x80 else disp - 0x100
                return f"${disp_signed:X}(PC,{xtype}{xreg}{xsize})"
            elif reg == 4:  # #imm
                if size == 0:  # byte
                    imm = self.read_word() & 0xFF
                    return f"#${imm:02X}"
                elif size == 1:  # word
                    imm = self.read_word()
                    return f"#${imm:04X}"
                elif size == 2:  # long
                    imm = self.read_long()
                    return f"#${imm:08X}"
        return "???"

    def disassemble_instruction(self):
        """Disassemble one instruction"""
        start_pc = self.pc
        self.cycles = 0
        self.has_mem_access = False
        opcode = self.read_word()

        # MOVE
        if (opcode & 0xC000) == 0x0000 and (opcode & 0x3000) != 0x0000:
            size_map = {1: 0, 3: 1, 2: 2}  # 01=byte, 11=word, 10=long
            size_code = (opcode >> 12) & 3
            if size_code in size_map:
                size = size_map[size_code]
                src_mode = (opcode >> 3) & 7
                src_reg = opcode & 7
                dst_mode = (opcode >> 6) & 7
                dst_reg = (opcode >> 9) & 7

                # Skip if dst_mode == 1 (address register), that's MOVEA
                if dst_mode == 1:
                    pass  # Let MOVEA handle it
                else:
                    src = self.decode_ea(src_mode, src_reg, size)
                    dst = self.decode_ea(dst_mode, dst_reg, size)

                    # Calculate cycles: base 4 + src EA + dst EA
                    src_read, _ = self.get_ea_cycles(src_mode, src_reg, size)
                    _, dst_write = self.get_ea_cycles(dst_mode, dst_reg, size)
                    self.cycles = 4 + src_read + dst_write

                    # Check for memory access (either source or destination)
                    self.has_mem_access = (self.check_mem_access(src_mode, src_reg) or 
                                          self.check_mem_access(dst_mode, dst_reg))

                    return f"MOVE{self.get_size_suffix(size)} {src},{dst}"

        # MOVEA
        if (opcode & 0xC000) == 0x0000 and ((opcode >> 12) & 3) in [3, 2]:
            size = 1 if ((opcode >> 12) & 3) == 3 else 2
            src_mode = (opcode >> 3) & 7
            src_reg = opcode & 7
            dst_reg = (opcode >> 9) & 7

            src = self.decode_ea(src_mode, src_reg, size)

            # Calculate cycles: base 4 + src EA
            src_read, _ = self.get_ea_cycles(src_mode, src_reg, size)
            self.cycles = 4 + src_read
            self.has_mem_access = self.check_mem_access(src_mode, src_reg)

            return f"MOVEA{self.get_size_suffix(size)} {src},A{dst_reg}"

        # Immediate operations (ORI, ANDI, SUBI, ADDI, EORI, CMPI)
        if (opcode & 0xFF00) in [0x0000, 0x0200, 0x0400, 0x0600, 0x0A00, 0x0C00]:
            op_map = {0x00: 'ORI', 0x02: 'ANDI', 0x04: 'SUBI', 0x06: 'ADDI', 
                     0x0A: 'EORI', 0x0C: 'CMPI'}
            op = op_map[(opcode >> 8) & 0x0F]
            size = (opcode >> 6) & 3
            if size <= 2:
                ea_mode = (opcode >> 3) & 7
                ea_reg = opcode & 7

                imm = self.decode_ea(7, 4, size)
                dst = self.decode_ea(ea_mode, ea_reg, size)

                # Base cycles
                if ea_mode == 0:  # Dn
                    if size == 2:  # long
                        self.cycles = 16 if op == 'CMPI' else 16
                    else:
                        self.cycles = 8
                else:
                    if size == 2:
                        self.cycles = 20 if op == 'CMPI' else 20
                    else:
                        self.cycles = 12 if op == 'CMPI' else 12
                    ea_read, ea_write = self.get_ea_cycles(ea_mode, ea_reg, size)
                    if op == 'CMPI':
                        self.cycles += ea_read
                    else:
                        self.cycles += ea_read

                self.has_mem_access = self.check_mem_access(ea_mode, ea_reg)
                return f"{op}{self.get_size_suffix(size)} {imm},{dst}"

        # MOVEQ
        if (opcode & 0xF100) == 0x7000:
            reg = (opcode >> 9) & 7
            data = opcode & 0xFF
            data_signed = data if data < 0x80 else data - 0x100
            self.cycles = 4
            self.has_mem_access = False
            return f"MOVEQ #${data:02X},D{reg}"

        # EXG (must come before AND due to opcode overlap)
        if (opcode & 0xF130) == 0xC100:
            rx = (opcode >> 9) & 7
            ry = opcode & 7
            opmode = (opcode >> 3) & 0x1F
            self.cycles = 6
            self.has_mem_access = False

            if opmode == 0x08:
                return f"EXG D{rx},D{ry}"
            elif opmode == 0x09:
                return f"EXG A{rx},A{ry}"
            elif opmode == 0x11:
                return f"EXG D{rx},A{ry}"

        # ADD, SUB, AND, OR, EOR
        for base, mnem in [(0x9000, 'SUB'), (0xD000, 'ADD'), (0xC000, 'AND'), 
                           (0x8000, 'OR'), (0xB000, 'EOR')]:
            if (opcode & 0xF000) == base:
                reg = (opcode >> 9) & 7
                opmode = (opcode >> 6) & 7
                ea_mode = (opcode >> 3) & 7
                ea_reg = opcode & 7

                size = opmode & 3
                if size <= 2:
                    direction = (opmode >> 2) & 1
                    if direction == 0:  # EA to Dn
                        src = self.decode_ea(ea_mode, ea_reg, size)
                        # Base cycles: byte/word=4, long=6/8
                        if size == 2:  # long
                            self.cycles = 8 if ea_mode == 0 else 6
                        else:
                            self.cycles = 4
                        src_read, _ = self.get_ea_cycles(ea_mode, ea_reg, size)
                        self.cycles += src_read
                        self.has_mem_access = self.check_mem_access(ea_mode, ea_reg)
                        return f"{mnem}{self.get_size_suffix(size)} {src},D{reg}"
                    else:  # Dn to EA
                        dst = self.decode_ea(ea_mode, ea_reg, size)
                        # Base cycles + EA write
                        self.cycles = 8 if size == 2 else 4
                        _, ea_write = self.get_ea_cycles(ea_mode, ea_reg, size)
                        self.cycles += ea_write
                        self.has_mem_access = self.check_mem_access(ea_mode, ea_reg)
                        return f"{mnem}{self.get_size_suffix(size)} D{reg},{dst}"

        # CMP
        if (opcode & 0xF000) == 0xB000:
            reg = (opcode >> 9) & 7
            opmode = (opcode >> 6) & 7
            ea_mode = (opcode >> 3) & 7
            ea_reg = opcode & 7

            if opmode in [0, 1, 2]:  # CMP
                size = opmode
                src = self.decode_ea(ea_mode, ea_reg, size)
                # Base 4 cycles + EA
                self.cycles = 4
                src_read, _ = self.get_ea_cycles(ea_mode, ea_reg, size)
                self.cycles += src_read
                self.has_mem_access = self.check_mem_access(ea_mode, ea_reg)
                return f"CMP{self.get_size_suffix(size)} {src},D{reg}"
            elif opmode in [3, 7]:  # CMPA
                size = 1 if opmode == 3 else 2
                src = self.decode_ea(ea_mode, ea_reg, size)
                self.cycles = 6
                src_read, _ = self.get_ea_cycles(ea_mode, ea_reg, size)
                self.cycles += src_read
                self.has_mem_access = self.check_mem_access(ea_mode, ea_reg)
                return f"CMPA{self.get_size_suffix(size)} {src},A{reg}"

        # LEA
        if (opcode & 0xF1C0) == 0x41C0:
            reg = (opcode >> 9) & 7
            ea_mode = (opcode >> 3) & 7
            ea_reg = opcode & 7
            src = self.decode_ea(ea_mode, ea_reg, 2)
            # LEA timing depends on addressing mode
            if ea_mode == 2:  # (An)
                self.cycles = 4
            elif ea_mode == 5:  # d16(An)
                self.cycles = 8
            elif ea_mode == 6:  # d8(An,Xn)
                self.cycles = 12
            elif ea_mode == 7:
                if ea_reg == 0:  # xxx.W
                    self.cycles = 8
                elif ea_reg == 1:  # xxx.L
                    self.cycles = 12
                elif ea_reg == 2:  # d16(PC)
                    self.cycles = 8
                elif ea_reg == 3:  # d8(PC,Xn)
                    self.cycles = 12
            self.has_mem_access = False  # LEA calculates address, doesn't access memory
            return f"LEA {src},A{reg}"

        # SWAP (must come before PEA due to opcode overlap)
        if (opcode & 0xFFF8) == 0x4840:
            reg = opcode & 7
            self.cycles = 4
            self.has_mem_access = False
            return f"SWAP D{reg}"

        # PEA
        if (opcode & 0xFFC0) == 0x4840:
            ea_mode = (opcode >> 3) & 7
            ea_reg = opcode & 7
            src = self.decode_ea(ea_mode, ea_reg, 2)
            # PEA timing similar to LEA + stack write
            if ea_mode == 2:
                self.cycles = 12
            elif ea_mode == 5:
                self.cycles = 16
            elif ea_mode == 6:
                self.cycles = 20
            elif ea_mode == 7:
                if ea_reg == 0:
                    self.cycles = 16
                elif ea_reg == 1:
                    self.cycles = 20
                elif ea_reg == 2:
                    self.cycles = 16
                elif ea_reg == 3:
                    self.cycles = 20
            self.has_mem_access = True  # PEA writes to stack
            return f"PEA {src}"

        # CLR, NEG, NEGX, NOT, TST
        for mask, base, mnem in [(0xFF00, 0x4200, 'CLR'), (0xFF00, 0x4400, 'NEG'),
                                  (0xFF00, 0x4000, 'NEGX'), (0xFF00, 0x4600, 'NOT'),
                                  (0xFF00, 0x4A00, 'TST')]:
            if (opcode & mask) == base:
                size = (opcode >> 6) & 3
                if size <= 2:
                    ea_mode = (opcode >> 3) & 7
                    ea_reg = opcode & 7
                    ea = self.decode_ea(ea_mode, ea_reg, size)
                    # Base cycles
                    if ea_mode == 0:  # Dn
                        self.cycles = 4 if size != 2 else 6
                    else:
                        if mnem == 'TST':  # TST doesn't write
                            self.cycles = 4
                            ea_read, _ = self.get_ea_cycles(ea_mode, ea_reg, size)
                            self.cycles += ea_read
                        else:  # Others read and write
                            self.cycles = 8 if size != 2 else 12
                            ea_read, _ = self.get_ea_cycles(ea_mode, ea_reg, size)
                            self.cycles += ea_read
                    self.has_mem_access = self.check_mem_access(ea_mode, ea_reg)
                    return f"{mnem}{self.get_size_suffix(size)} {ea}"

        # JMP, JSR
        if (opcode & 0xFFC0) == 0x4EC0:
            ea_mode = (opcode >> 3) & 7
            ea_reg = opcode & 7
            ea = self.decode_ea(ea_mode, ea_reg, 2)
            # JMP timing
            if ea_mode == 2:  # (An)
                self.cycles = 8
            elif ea_mode == 5:  # d16(An)
                self.cycles = 10
            elif ea_mode == 6:  # d8(An,Xn)
                self.cycles = 14
            elif ea_mode == 7:
                if ea_reg == 0:  # xxx.W
                    self.cycles = 10
                elif ea_reg == 1:  # xxx.L
                    self.cycles = 12
                elif ea_reg == 2:  # d16(PC)
                    self.cycles = 10
                elif ea_reg == 3:  # d8(PC,Xn)
                    self.cycles = 14
            self.has_mem_access = False
            return f"JMP {ea}"

        if (opcode & 0xFFC0) == 0x4E80:
            ea_mode = (opcode >> 3) & 7
            ea_reg = opcode & 7
            ea = self.decode_ea(ea_mode, ea_reg, 2)
            # JSR timing (JMP + 8 for stack)
            if ea_mode == 2:
                self.cycles = 16
            elif ea_mode == 5:
                self.cycles = 18
            elif ea_mode == 6:
                self.cycles = 22
            elif ea_mode == 7:
                if ea_reg == 0:
                    self.cycles = 18
                elif ea_reg == 1:
                    self.cycles = 20
                elif ea_reg == 2:
                    self.cycles = 18
                elif ea_reg == 3:
                    self.cycles = 22
            self.has_mem_access = True  # JSR writes to stack
            return f"JSR {ea}"

        # Bcc (conditional branches)
        if (opcode & 0xF000) == 0x6000:
            cc = (opcode >> 8) & 0x0F
            disp = opcode & 0xFF

            if disp == 0:
                disp = self.read_word()
                disp_signed = disp if disp < 0x8000 else disp - 0x10000
            else:
                disp_signed = disp if disp < 0x80 else disp - 0x100

            target = start_pc + 2 + disp_signed

            # Branch timing: 10 if taken, 8 if not taken (we show taken)
            # BRA and BSR are always taken
            if cc == 0:
                self.cycles = 10
                self.has_mem_access = False
                return f"BRA ${target:X}"
            elif cc == 1:
                self.cycles = 18  # BSR includes subroutine linkage
                self.has_mem_access = True  # Writes to stack
                return f"BSR ${target:X}"
            else:
                self.cycles = 10  # Showing taken cycles
                self.has_mem_access = False
                return f"B{self.get_condition(cc)} ${target:X}"

        # DBcc
        if (opcode & 0xF0F8) == 0x50C8:
            cc = (opcode >> 8) & 0x0F
            reg = opcode & 7
            disp = self.read_word()
            disp_signed = disp if disp < 0x8000 else disp - 0x10000
            target = start_pc + 2 + disp_signed
            # DBcc: 10 if branch, 12-14 if no branch (counter expired)
            self.cycles = 10
            self.has_mem_access = False
            return f"DB{self.get_condition(cc)} D{reg},${target:X}"

        # Scc
        if (opcode & 0xF0C0) == 0x50C0:
            cc = (opcode >> 8) & 0x0F
            ea_mode = (opcode >> 3) & 7
            ea_reg = opcode & 7
            ea = self.decode_ea(ea_mode, ea_reg, 0)
            # Scc: 4-6 cycles if false + EA, 6-8 if true + EA
            if ea_mode == 0:
                self.cycles = 6  # True case
            else:
                self.cycles = 8
                _, ea_write = self.get_ea_cycles(ea_mode, ea_reg, 0)
                self.cycles += ea_write
            self.has_mem_access = self.check_mem_access(ea_mode, ea_reg)
            return f"S{self.get_condition(cc)} {ea}"

        # RTS, RTE, RTR
        if opcode == 0x4E75:
            self.cycles = 16
            self.has_mem_access = True  # Reads from stack
            return "RTS"
        if opcode == 0x4E73:
            self.cycles = 20
            self.has_mem_access = True  # Reads from stack
            return "RTE"
        if opcode == 0x4E77:
            self.cycles = 20
            self.has_mem_access = True  # Reads from stack
            return "RTR"

        # NOP
        if opcode == 0x4E71:
            self.cycles = 4
            self.has_mem_access = False
            return "NOP"

        # TRAP
        if (opcode & 0xFFF0) == 0x4E40:
            vector = opcode & 0x0F
            self.cycles = 34
            self.has_mem_access = True
            return f"TRAP #{vector}"

        # LINK, UNLK
        if (opcode & 0xFFF8) == 0x4E50:
            reg = opcode & 7
            disp = self.read_word()
            disp_signed = disp if disp < 0x8000 else disp - 0x10000
            self.cycles = 16
            self.has_mem_access = True  # Writes to stack
            return f"LINK A{reg},#${disp_signed:X}"

        if (opcode & 0xFFF8) == 0x4E58:
            reg = opcode & 7
            self.cycles = 12
            self.has_mem_access = True  # Reads from stack
            return f"UNLK A{reg}"

        # EXT
        if (opcode & 0xFEB8) == 0x4880:
            opmode = (opcode >> 6) & 7
            reg = opcode & 7
            self.cycles = 4
            self.has_mem_access = False
            if opmode == 2:
                return f"EXT.W D{reg}"
            elif opmode == 3:
                return f"EXT.L D{reg}"

        # Shift/Rotate (register)
        if (opcode & 0xF000) == 0xE000 and (opcode & 0x00C0) != 0x00C0:
            count_reg = (opcode >> 9) & 7
            dr = (opcode >> 8) & 1
            size = (opcode >> 6) & 3
            ir = (opcode >> 5) & 1
            mode = (opcode >> 3) & 3
            reg = opcode & 7

            if size <= 2:
                ops = ['AS', 'LS', 'ROX', 'RO']
                op = ops[mode]
                direction = 'L' if dr else 'R'

                # Shift/rotate timing: 6 + 2*n where n is shift count
                if ir:
                    # Count is in register - use worst case (max shift of 63)
                    self.cycles = 6 + 2 * 8  # Assuming typical case
                    count_str = f"D{count_reg}"
                else:
                    count = count_reg if count_reg != 0 else 8
                    self.cycles = 6 + 2 * count
                    count_str = f"#{count}"

                self.has_mem_access = False
                return f"{op}{direction}{self.get_size_suffix(size)} {count_str},D{reg}"

        # Memory shift/rotate
        if (opcode & 0xFEC0) == 0xE0C0:
            dr = (opcode >> 8) & 1
            mode = (opcode >> 9) & 3
            ea_mode = (opcode >> 3) & 7
            ea_reg = opcode & 7

            ops = ['AS', 'LS', 'ROX', 'RO']
            op = ops[mode]
            direction = 'L' if dr else 'R'
            ea = self.decode_ea(ea_mode, ea_reg, 1)

            # Memory shifts: 8 base + EA time
            self.cycles = 8
            ea_read, ea_write = self.get_ea_cycles(ea_mode, ea_reg, 1)
            self.cycles += ea_read + ea_write
            self.has_mem_access = True

            return f"{op}{direction} {ea}"
            ea_mode = (opcode >> 3) & 7
            ea_reg = opcode & 7

            ops = ['AS', 'LS', 'ROX', 'RO']
            op = ops[mode]
            direction = 'L' if dr else 'R'
            ea = self.decode_ea(ea_mode, ea_reg, 1)

            return f"{op}{direction} {ea}"

        # MOVEM
        if (opcode & 0xFB80) == 0x4880:
            dr = (opcode >> 10) & 1
            size = 1 if (opcode & 0x0040) else 2
            ea_mode = (opcode >> 3) & 7
            ea_reg = opcode & 7

            mask = self.read_word()
            regs = []
            reg_count = 0

            # For -(An) mode, register order is reversed
            if ea_mode == 4:
                # For predecrement: bit 0=A7, bit 1=A6, ..., bit 7=A0
                #                   bit 8=D7, bit 9=D6, ..., bit 15=D0
                for i in range(8):
                    if mask & (1 << i):
                        regs.append(f"A{7-i}")
                        reg_count += 1
                for i in range(8):
                    if mask & (1 << (i + 8)):
                        regs.append(f"D{7-i}")
                        reg_count += 1
            else:
                # Normal mode: bit 0=D0, bit 1=D1, ..., bit 7=D7
                #              bit 8=A0, bit 9=A1, ..., bit 15=A7
                for i in range(8):
                    if mask & (1 << i):
                        regs.append(f"D{i}")
                        reg_count += 1
                for i in range(8):
                    if mask & (1 << (i + 8)):
                        regs.append(f"A{i}")
                        reg_count += 1

            reglist = '/'.join(regs) if regs else ''
            ea = self.decode_ea(ea_mode, ea_reg, size)

            # MOVEM timing: 8 + 4*n (word) or 8 + 8*n (long) for memory to register
            # or 8 + 4*n (word) or 8 + 8*n (long) for register to memory
            if size == 1:  # word
                self.cycles = 8 + 4 * reg_count
            else:  # long
                self.cycles = 8 + 8 * reg_count

            # Add EA calculation time for non-simple modes
            if ea_mode == 5:  # d16(An)
                self.cycles += 4
            elif ea_mode == 6:  # d8(An,Xn)
                self.cycles += 6

            self.has_mem_access = True

            if dr:
                return f"MOVEM{self.get_size_suffix(size)} {ea},{reglist}"
            else:
                return f"MOVEM{self.get_size_suffix(size)} {reglist},{ea}"

        # MULU, MULS, DIVU, DIVS
        for base, mnem in [(0xC0C0, 'MULU'), (0xC1C0, 'MULS'), 
                           (0x80C0, 'DIVU'), (0x81C0, 'DIVS')]:
            if (opcode & 0xF1C0) == base:
                reg = (opcode >> 9) & 7
                ea_mode = (opcode >> 3) & 7
                ea_reg = opcode & 7
                src = self.decode_ea(ea_mode, ea_reg, 1)
                # Multiply: ~70 cycles, Divide: ~140 cycles (varies by data)
                if 'MUL' in mnem:
                    self.cycles = 70  # Approximate, varies 38-70
                else:
                    self.cycles = 140  # Approximate, varies 76-140
                src_read, _ = self.get_ea_cycles(ea_mode, ea_reg, 1)
                self.cycles += src_read
                self.has_mem_access = self.check_mem_access(ea_mode, ea_reg)
                return f"{mnem} {src},D{reg}"

        return f"DC.w ${opcode:04X}  ; Unknown instruction"

    def disassemble(self, hex_string, start_address=0):
        """Disassemble a hex string"""
        # Remove spaces and convert to bytes
        hex_string = hex_string.replace(' ', '').replace('\n', '').replace('\r', '')

        if len(hex_string) % 2 != 0:
            raise ValueError("Hex string must have even number of digits")

        self.data = bytes.fromhex(hex_string)
        self.pc = 0

        results = []
        while self.pc < len(self.data):
            addr = start_address + self.pc
            try:
                instr = self.disassemble_instruction()
                cycle_info = self.format_cycles(self.cycles, self.has_mem_access)
                results.append(f"{addr:08X}: {instr:<40} ; {cycle_info}")
            except Exception as e:
                results.append(f"{addr:08X}: Error - {e}")
                break

        return '\n'.join(results)


def main():
    disasm = M68kDisassembler()

    if len(sys.argv) > 1:
        # Command line argument mode
        hex_input = ' '.join(sys.argv[1:])
        try:
            print(disasm.disassemble(hex_input))
        except Exception as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)
    else:
        # Interactive mode
        print("Motorola 68000 Disassembler")
        print("Enter hex bytes (e.g., '4E75' or '4E 75'), or 'quit' to exit")
        print()

        while True:
            try:
                hex_input = input(">>> ").strip()

                if hex_input.lower() in ['quit', 'exit', 'q']:
                    break

                if not hex_input:
                    continue

                print(disasm.disassemble(hex_input))
                print()

            except EOFError:
                break
            except KeyboardInterrupt:
                print("\nExiting...")
                break
            except Exception as e:
                print(f"Error: {e}")
                print()


if __name__ == '__main__':
    main()

