"""The `.dat` container: a 2,048-byte directory and sector-aligned chunks.

Every graphics, level, map and enemy file on this disc is the same shape:

    u16       count
    u32 x N   chunk sizes, in order
    ...       zero padding out to 2,048 bytes
    chunk 0   at 0x800, padded up to the next 2,048-byte boundary
    chunk 1   ...

Chaining the sizes lands **exactly** on the file size for all 45 containers,
which is what makes the layout certain rather than plausible. `check` is that
test.

Three files in the root are not containers and say so by having count 0 or
nonsense: `demo1.dat`, `demo2.dat`, `demo3.dat` (recorded controller input for
the attract mode) and `map7_1.dat`..`map7_5.dat` (a bare map array with no tile
sheet and no palette of its own).

  python tools/cdidat.py list [FILE...]     per-file chunk table
  python tools/cdidat.py check              chain every container, report misses
  python tools/cdidat.py census             classify chunks, find shared ones
  python tools/cdidat.py extract OUTDIR     write every chunk out
"""
import os, sys, struct, hashlib, collections, argparse

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

FILES = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '_work', 'files')
NOT_CONTAINERS = {'demo1.dat', 'demo2.dat', 'demo3.dat',
                  'map7_1.dat', 'map7_2.dat', 'map7_3.dat', 'map7_4.dat', 'map7_5.dat'}


def parse(path):
    """-> (chunks, end_offset). chunks is a list of (index, offset, size, bytes)."""
    d = open(path, 'rb').read()
    count = struct.unpack('>H', d[:2])[0]
    if count == 0 or 2 + 4 * count > 2048:
        return None, len(d), d
    sizes = [struct.unpack('>I', d[2 + 4 * i:6 + 4 * i])[0] for i in range(count)]
    out, off = [], 0x800
    for i, s in enumerate(sizes):
        if off + s > len(d):
            return None, off, d
        out.append((i, off, s, d[off:off + s]))
        off += (s + 2047) // 2048 * 2048
    return out, off, d


def each(names=None):
    names = names or sorted(f for f in os.listdir(FILES) if f.endswith('.dat'))
    for n in names:
        yield n, os.path.join(FILES, n)


def classify(c):
    """What a chunk looks like, from three cheap measurements."""
    if len(c) in (384, 768) and len(c) % 3 == 0:
        return f'palette, {len(c) // 3} RGB entries'
    if len(c) >= 8 and c[:4] == b'\0\0\0\0' and c[4:6] == b'\x60\x00':
        return '68000 code (BRA.W jump table at offset 4)'
    mx = max(c) if c else 0
    if mx <= 0x7f:
        return f'8bpp pixels, max index 0x{mx:02x} -> CLUT7'
    return f'structured/mixed, max byte 0x{mx:02x}'


def cmd_list(names):
    for n, p in each(names):
        chunks, end, d = parse(p)
        if chunks is None:
            print(f'{n}: {len(d):,} B  -- not a container')
            continue
        print(f'{n}: {len(chunks)} chunks, {len(d):,} B')
        for i, off, s, c in chunks:
            print(f'   #{i} @0x{off:06x} {s:9,} B  {classify(c)}')


def cmd_check(names):
    good = bad = skipped = 0
    for n, p in each(names):
        chunks, end, d = parse(p)
        if chunks is None:
            skipped += 1
            continue
        if end == len(d):
            good += 1
        else:
            bad += 1
            print(f'{n}: chain ends 0x{end:x}, file is 0x{len(d):x}')
    print(f'{good} containers close exactly, {bad} do not, '
          f'{skipped} are not containers')


def cmd_census(names):
    H = collections.defaultdict(list)
    total = 0
    for n, p in each(names):
        chunks, end, d = parse(p)
        if chunks is None:
            continue
        for i, off, s, c in chunks:
            H[hashlib.md5(c).hexdigest()].append((n, i, s))
            total += 1
    print(f'{total} chunks, {len(H)} distinct\n')
    print('chunks that appear in more than one file:')
    for h, v in sorted(H.items(), key=lambda kv: (-len(kv[1]), -kv[1][0][2])):
        if len(v) > 1:
            names_ = ', '.join(f'{a}#{b}' for a, b, _ in v[:6])
            print(f'   {v[0][2]:9,} B  x{len(v):3d}  {names_}'
                  f'{" ..." if len(v) > 6 else ""}')


def cmd_extract(outdir, names):
    os.makedirs(outdir, exist_ok=True)
    for n, p in each(names):
        chunks, end, d = parse(p)
        if chunks is None:
            continue
        for i, off, s, c in chunks:
            open(os.path.join(outdir, f'{n[:-4]}_{i}.bin'), 'wb').write(c)
    print(f'chunks written to {outdir}')


if __name__ == '__main__':
    ap = argparse.ArgumentParser()
    ap.add_argument('cmd', choices=['list', 'check', 'census', 'extract'])
    ap.add_argument('args', nargs='*')
    a = ap.parse_args()
    if a.cmd == 'extract':
        cmd_extract(a.args[0] if a.args else '_work/chunks', a.args[1:] or None)
    else:
        {'list': cmd_list, 'check': cmd_check, 'census': cmd_census}[a.cmd](a.args or None)

