void c_func_divu (ea_t *ea, int reg)
{
	char buf[256];
	c_fncall ();

	c_fnbegin ();
	c_readea (ea, buf);
	cln ("s16 src = %s;\n", buf);
	cln ("s32 dest = Regs[%d]._s32;", reg);
	cln ("if (src == 0) {");
	ifV { cln ("	V = 0;"); }
