// Package atr handles ATR disk image header parsing, loading, and encoding.
//
// ATR is a 16-byte header format for Atari 8-bit disk images.
// Sector sizes: 128 (SD/ED) or 256 (DD).
// DD images store the first 3 boot sectors as 128 bytes in the file.
// Sectors are numbered from 1; sector 0 does not exist.
package atr

import (
	"fmt"
	"os"

	"atrfs/internal/logutil"
)

const HeaderSize = 16

var Magic = [2]byte{0x96, 0x02}

// Header represents a parsed 16-byte ATR header.
type Header struct {
	SectorSize    int // 128 or 256
	SectorCount   int // total number of sectors
	ImageDataSize int // raw data size from header (bytes)
}

// Image is a loaded ATR disk image with normalized sector storage.
// All sectors are stored at full SectorSize in Data, even DD boot sectors.
type Image struct {
	Path   string
	Header Header
	Data   []byte // mutable sector data (len = SectorCount * SectorSize)
}

// SectorSize returns the sector size.
func (img *Image) SectorSize() int { return img.Header.SectorSize }

// SectorCount returns the total number of sectors.
func (img *Image) SectorCount() int { return img.Header.SectorCount }

// GetSector returns sector data by 1-based sector number.
func (img *Image) GetSector(num int) ([]byte, error) {
	if num < 1 || num > img.Header.SectorCount {
		return nil, fmt.Errorf("sector %d out of range [1, %d]", num, img.Header.SectorCount)
	}
	ofs := (num - 1) * img.Header.SectorSize
	end := ofs + img.Header.SectorSize
	dst := make([]byte, img.Header.SectorSize)
	copy(dst, img.Data[ofs:end])
	return dst, nil
}

// SetSector writes sector data by 1-based sector number.
func (img *Image) SetSector(num int, data []byte) error {
	if num < 1 || num > img.Header.SectorCount {
		return fmt.Errorf("sector %d out of range [1, %d]", num, img.Header.SectorCount)
	}
	if len(data) != img.Header.SectorSize {
		return fmt.Errorf("sector data must be %d bytes, got %d", img.Header.SectorSize, len(data))
	}
	ofs := (num - 1) * img.Header.SectorSize
	copy(img.Data[ofs:ofs+img.Header.SectorSize], data)
	return nil
}

// ParseHeader parses a 16-byte ATR header.
func ParseHeader(data []byte) (Header, error) {
	if len(data) < HeaderSize {
		return Header{}, fmt.Errorf("ATR header requires %d bytes, got %d", HeaderSize, len(data))
	}
	if data[0] != Magic[0] || data[1] != Magic[1] {
		return Header{}, fmt.Errorf("bad ATR magic: 0x%02X 0x%02X (expected 0x96 0x02)", data[0], data[1])
	}

	sectorSize := int(data[4]) | (int(data[5]) << 8)
	if sectorSize != 128 && sectorSize != 256 {
		return Header{}, fmt.Errorf("unsupported ATR sector size: %d", sectorSize)
	}

	imageDataSize := (int(data[2]) << 4) | (int(data[3]) << 12) | (int(data[6]) << 20)
	if imageDataSize == 0 {
		return Header{}, fmt.Errorf("ATR image data size is zero")
	}

	var sectorCount int
	if sectorSize == 256 {
		remainder := imageDataSize % sectorSize
		if remainder == 0 {
			sectorCount = imageDataSize / sectorSize
		} else {
			padSize := 3 * (256 - 128)
			sectorCount = (imageDataSize + padSize) / sectorSize
		}
	} else {
		sectorCount = imageDataSize / sectorSize
	}

	if sectorCount == 0 {
		return Header{}, fmt.Errorf("ATR image has no sectors")
	}

	return Header{SectorSize: sectorSize, SectorCount: sectorCount, ImageDataSize: imageDataSize}, nil
}

// EncodeHeader produces a 16-byte ATR header for the given geometry.
func EncodeHeader(sectorSize, sectorCount int) []byte {
	var imageDataSize int
	if sectorSize == 256 && sectorCount > 3 {
		imageDataSize = 3*128 + (sectorCount-3)*256
	} else if sectorSize == 256 {
		imageDataSize = sectorCount * 128
	} else {
		imageDataSize = sectorCount * sectorSize
	}

	hdr := make([]byte, HeaderSize)
	hdr[0] = 0x96
	hdr[1] = 0x02
	hdr[2] = byte((imageDataSize >> 4) & 0xFF)
	hdr[3] = byte((imageDataSize >> 12) & 0xFF)
	hdr[4] = byte(sectorSize & 0xFF)
	hdr[5] = byte((sectorSize >> 8) & 0xFF)
	hdr[6] = byte((imageDataSize >> 20) & 0xFF)
	return hdr
}

// LoadImage loads an ATR disk image from file. Normalizes sector storage.
func LoadImage(path string) (*Image, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	if len(raw) < HeaderSize {
		return nil, fmt.Errorf("file too small for ATR header: %d bytes", len(raw))
	}

	header, err := ParseHeader(raw[:HeaderSize])
	if err != nil {
		return nil, err
	}

	fileData := raw[HeaderSize:]
	data := make([]byte, header.SectorCount*header.SectorSize)
	filePos := 0

	for i := 0; i < header.SectorCount; i++ {
		readSize := header.SectorSize
		if i < 3 && header.SectorSize == 256 {
			readSize = 128
		}
		if filePos+readSize > len(fileData) {
			logutil.Warn("ATR file truncated at sector %d", i+1)
			break
		}
		ofs := i * header.SectorSize
		copy(data[ofs:ofs+readSize], fileData[filePos:filePos+readSize])
		filePos += readSize
	}

	return &Image{Path: path, Header: header, Data: data}, nil
}

// LoadImageFromBytes loads an ATR image from raw bytes (for testing).
func LoadImageFromBytes(raw []byte) (*Image, error) {
	if len(raw) < HeaderSize {
		return nil, fmt.Errorf("data too small for ATR header: %d bytes", len(raw))
	}

	header, err := ParseHeader(raw[:HeaderSize])
	if err != nil {
		return nil, err
	}

	fileData := raw[HeaderSize:]
	data := make([]byte, header.SectorCount*header.SectorSize)
	filePos := 0

	for i := 0; i < header.SectorCount; i++ {
		readSize := header.SectorSize
		if i < 3 && header.SectorSize == 256 {
			readSize = 128
		}
		if filePos+readSize > len(fileData) {
			break
		}
		ofs := i * header.SectorSize
		copy(data[ofs:ofs+readSize], fileData[filePos:filePos+readSize])
		filePos += readSize
	}

	return &Image{Path: "<bytes>", Header: header, Data: data}, nil
}

// EncodeImage encodes an ATR image to bytes (header + sector data).
func EncodeImage(img *Image) []byte {
	hdr := EncodeHeader(img.Header.SectorSize, img.Header.SectorCount)
	result := make([]byte, 0, len(hdr)+len(img.Data))
	result = append(result, hdr...)

	for i := 0; i < img.Header.SectorCount; i++ {
		ofs := i * img.Header.SectorSize
		if i < 3 && img.Header.SectorSize == 256 {
			result = append(result, img.Data[ofs:ofs+128]...)
		} else {
			result = append(result, img.Data[ofs:ofs+img.Header.SectorSize]...)
		}
	}
	return result
}

// Clone returns a deep copy of the image.
func (img *Image) Clone() *Image {
	dataCopy := make([]byte, len(img.Data))
	copy(dataCopy, img.Data)
	return &Image{Path: img.Path, Header: img.Header, Data: dataCopy}
}

