    CHECKOVERFLOW();
#ifdef __GNUC__
    wordptr = (unsigned short *)&MEM(sp - 1);
#else
    tempword = sp - 1;
    wordptr = (unsigned short *)&MEM(tempword);
#endif
    fp = *wordptr;
    ++pc;
}

