    __asm__("    sta     ptr1");
    __asm__("    lda     #$00");
    __asm__("    adc     #>(_jumptbl)");
    __asm__("    sta     ptr1+1");
    __asm__("    ldy     #$01");
    __asm__("    lda     (ptr1),y");
